SELECT srn.id, srnd.id as detailId, srn.source_id AS sourceId, srnd.source_detail_id AS sourceDetailId, srn.code, srn.source_code AS sourceCode, srn.so_code AS soCode, srn.approve_status AS approveStatus, srn.invalid_status AS invalidStatus, srn.customer_id AS customerId, srn.customer_name AS customerName, srn.inventory_org_id AS inventoryOrgId, srn.inventory_org_name AS inventoryOrgName, srn.seller_name AS sellerName, srnd.sku_id AS skuId, srnd.sku_no AS skuNo, srnd.return_qty AS returnQty, srn.bill_date AS billDate, srn.approve_user_name AS approveUserName, srn.create_user_name AS createUserName, srnd.return_type_dict AS returnTypeDict, srnd.return_reason_dict AS returnReasonDict, srn.create_time AS createTime FROM so_return_notice_detail srnd INNER JOIN so_return_notice srn ON srn.id = srnd.main_id AND srnd.is_deleted = FALSE WHERE ${params.sqlMap.default} and srn.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
srn.create_time desc

select count(distinct srn.id) FROM so_return_notice_detail srnd INNER JOIN so_return_notice srn ON srn.id = srnd.main_id AND srnd.is_deleted = FALSE WHERE srn.is_deleted = FALSE
and srn.approve_status in
#{item}
